-- Sivryn initial schema.
-- IDs are UUIDv7 generated by the server, so they sort by creation time.

CREATE TABLE users (
    id            UUID PRIMARY KEY,
    username      TEXT NOT NULL,
    display_name  TEXT,
    -- NULL for accounts that only sign in via OIDC.
    password_hash TEXT,
    oidc_subject  TEXT UNIQUE,
    is_admin      BOOLEAN NOT NULL DEFAULT FALSE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX users_username_lower ON users (lower(username));

CREATE TABLE sessions (
    -- SHA-256 of the bearer token; the token itself is never stored.
    token_hash BYTEA PRIMARY KEY,
    user_id    UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX sessions_user ON sessions (user_id);

CREATE TABLE guilds (
    id         UUID PRIMARY KEY,
    name       TEXT NOT NULL,
    owner_id   UUID NOT NULL REFERENCES users (id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE roles (
    id          UUID PRIMARY KEY,
    guild_id    UUID NOT NULL REFERENCES guilds (id) ON DELETE CASCADE,
    name        TEXT NOT NULL,
    permissions BIGINT NOT NULL,
    position    INT NOT NULL DEFAULT 0,
    -- The implicit role every member has.
    is_everyone BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE UNIQUE INDEX roles_one_everyone ON roles (guild_id) WHERE is_everyone;

CREATE TABLE guild_members (
    guild_id  UUID NOT NULL REFERENCES guilds (id) ON DELETE CASCADE,
    user_id   UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    joined_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (guild_id, user_id)
);
CREATE INDEX guild_members_user ON guild_members (user_id);

CREATE TABLE member_roles (
    guild_id UUID NOT NULL,
    user_id  UUID NOT NULL,
    role_id  UUID NOT NULL REFERENCES roles (id) ON DELETE CASCADE,
    PRIMARY KEY (guild_id, user_id, role_id),
    FOREIGN KEY (guild_id, user_id) REFERENCES guild_members (guild_id, user_id) ON DELETE CASCADE
);

CREATE TABLE channels (
    id       UUID PRIMARY KEY,
    guild_id UUID NOT NULL REFERENCES guilds (id) ON DELETE CASCADE,
    name     TEXT NOT NULL,
    kind     TEXT NOT NULL CHECK (kind IN ('text', 'voice')),
    position INT NOT NULL DEFAULT 0,
    e2ee     BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX channels_guild ON channels (guild_id, position);

CREATE TABLE invites (
    id         UUID PRIMARY KEY,
    code       TEXT NOT NULL UNIQUE,
    -- NULL: instance invite (allows registration when registration is invite-only).
    guild_id   UUID REFERENCES guilds (id) ON DELETE CASCADE,
    created_by UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    uses       INT NOT NULL DEFAULT 0,
    max_uses   INT,
    expires_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- MLS delivery service ----------------------------------------------------

CREATE TABLE devices (
    id         UUID PRIMARY KEY,
    user_id    UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name       TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX devices_user ON devices (user_id);

CREATE TABLE key_packages (
    id          BIGSERIAL PRIMARY KEY,
    device_id   UUID NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    key_package TEXT NOT NULL
);
CREATE INDEX key_packages_device ON key_packages (device_id);

-- Commits are strictly ordered per channel: the primary key rejects a second
-- commit for the same epoch, and the losing client has to catch up and retry.
CREATE TABLE mls_commits (
    channel_id UUID NOT NULL REFERENCES channels (id) ON DELETE CASCADE,
    epoch      BIGINT NOT NULL,
    device_id  UUID NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    commit     TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (channel_id, epoch)
);

CREATE TABLE pending_welcomes (
    id           BIGSERIAL PRIMARY KEY,
    device_id    UUID NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    channel_id   UUID NOT NULL REFERENCES channels (id) ON DELETE CASCADE,
    welcome      TEXT NOT NULL,
    ratchet_tree TEXT NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX pending_welcomes_device ON pending_welcomes (device_id);

CREATE TABLE messages (
    id               UUID PRIMARY KEY,
    channel_id       UUID NOT NULL REFERENCES channels (id) ON DELETE CASCADE,
    author_id        UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    sender_device_id UUID NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    epoch            BIGINT NOT NULL,
    -- MLS ciphertext; the server cannot read message contents.
    ciphertext       TEXT NOT NULL,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX messages_channel_id ON messages (channel_id, id DESC);
